<?php
// Routing is projected from existing orders. No migration or automatic reservation writes.
function oc_pending_cancellation($o){if($o['posting']!=='Not Posted'||oa_reported($o)['status']!=='Cancelled')return false;$held=(int)om_query('SELECT COALESCE(SUM(qty),0) FROM om_reservations WHERE order_id=?',[$o['id']])->fetchColumn();return $held>0||($o['platform_status']!=='Cancelled'&&oa_pending($o));}
function oc_ignore_resolved_report($o,$r){return $r['errors']===['Older export: keep the newer recorded status.']&&$o['monitoring']==='Resolved'&&oa_deferred($r['status'])&&$r['status']===oa_reported($o)['status']&&!oa_pending($o)&&!oc_pending_cancellation($o);}
function oc_return_pending($o){return $o['posting']==='Posted'&&oa_pending($o);}
function oc_next_action($o){if(oc_pending_cancellation($o))return 'Confirm pre-dispatch cancellation in Order Monitoring';if(oc_return_pending($o))return 'Receive actual returned items in Inflow, or resolve no-return outcome in Order Monitoring';if($o['posting']==='Not Posted'&&oa_pending($o))return 'Review missing dispatch evidence in Order Monitoring; no stock receipt allowed';return $o['monitoring']==='Resolved'?'Resolved':'Continue order monitoring';}
function oc_exception($o){if(oc_pending_cancellation($o))return 'Cancellation awaiting confirmation in Order Monitoring; reservation remains held';return $o['exception_text']??'';}
function oc_confirm_cancellation($id,$input){om_require();if(empty($input['warehouse_ack']))throw new Exception('Confirm all units remain in the warehouse and no dispatch was posted.');return process_transaction(function()use($id,$input){$o=om_order($id,true);if(!oc_pending_cancellation($o)||om_query('SELECT COUNT(*) FROM om_postings WHERE order_id=?',[$id])->fetchColumn())throw new Exception('Only an unposted cancellation can release reservations. Dispatched orders require actual return receiving.');$reason=process_reason($input['reason']??'');$held=(int)om_query('SELECT COALESCE(SUM(qty),0) FROM om_reservations WHERE order_id=?',[$id])->fetchColumn();om_release_all($id,'Cancellation confirmed in Order Monitoring');om_query("UPDATE om_orders SET platform_status='Cancelled',status_changed_at=NOW(),monitoring='Resolved',exception_text='',revision=revision+1 WHERE id=?",[$id]);om_event($id,null,'Cancellation confirmed in Order Monitoring',['source'=>'Order Monitoring','before_status'=>$o['platform_status'],'after_status'=>'Cancelled','reason'=>$reason,'physical_delta'=>0,'reservation_released'=>true,'released_units'=>$held]);audit('Confirm cancellation in Order Monitoring','Order Monitoring',$o['order_no'],$reason.'; released '.$held.' reserved pcs; physical stock unchanged.');om_alert_refresh();});}
function oc_pending_panel($platform){$rows=[];foreach(om_query('SELECT * FROM om_orders WHERE platform=? AND posting=? ORDER BY fulfillment_date,id',[$platform,'Not Posted']) as $o)if(oc_pending_cancellation($o))$rows[]=$o;if(!$rows)return;$offset=max(0,(int)($_GET['cancel_offset']??0));echo '<section class="card"><h3>Pending Pre-dispatch Cancellations · '.count($rows).'</h3><p>Includes previously reported cancellations. Confirm the items remain in the warehouse to release their reservation. Physical stock does not increase.</p>';$table=[];$links=[];foreach(array_slice($rows,$offset,10) as $o){$qty=(int)om_query('SELECT COALESCE(SUM(qty),0) FROM om_reservations WHERE order_id=?',[$o['id']])->fetchColumn();$table[]=[$o['order_no'],$o['fulfillment_date'],$o['platform_status'].' → Cancelled',$qty.' pcs','Order Monitoring'];$links[]=oi_buttons($o['id']);}om_table(['Order','Fulfillment','Status','Still Reserved','Next Action'],$table,$links);echo rs8_pagination(count($rows),$offset,10,$_GET,'cancel_offset').'</section>';}
function oc_resolution_panel($o){if(!om_allowed()||!oc_return_pending($o))return;echo '<div class="card"><h3>Refund Only / No Physical Return</h3><p>Use only for a verified no-return outcome. If goods actually return, receive them through Inflow.</p>';om_form('om_refund_only',['order_id'=>$o['id']]);echo '<label>Reason / verified reference<input name="reason" minlength="3" required></label><label class="oi-ack"><input type="checkbox" name="no_return_ack" value="1" required> No physical items will be returned or added to inventory.</label><button class="btn secondary">Confirm No-return Outcome · Physical 0</button></form></div>';}
function oc_inflow_panel(){if(!om_ready()||!can_action('return_confirm'))return;$rows=[];foreach(db()->query("SELECT * FROM om_orders WHERE posting='Posted' ORDER BY fulfillment_date,id") as $o)if(oc_return_pending($o)&&(!isset($_GET['pending_order'])||(int)$_GET['pending_order']===(int)$o['id']))$rows[]=$o;if(!$rows)return;$offset=max(0,(int)($_GET['pending_offset']??0));echo '<div class="card"><h3>Actual Return Follow-up · Dispatched Orders</h3><p>Receive only the items physically back in the warehouse. Pre-dispatch cancellations and no-return outcomes are handled in Order Monitoring.</p><div class="table-wrap"><table class="table"><thead><tr><th>Platform / Order</th><th>Reported Status</th><th>Physical Receiving</th></tr></thead><tbody>';foreach(array_slice($rows,$offset,10) as $o){echo '<tr><td>'.e($o['platform'].' · '.$o['order_no']).'</td><td>'.e(oa_reported($o)['status']).'</td><td><form method="post" action="actions.php">';workflow_hidden('receiving_load_reported',['order_record_id'=>$o['id'],'return'=>'inflow&entry=manual']);echo '<button class="btn secondary">Receive Actual Returned Items</button></form><a href="?page=order_monitor&amp;order_id='.(int)$o['id'].'">View order / no-return resolution</a></td></tr>';}echo '</tbody></table></div>'.rs8_pagination(count($rows),$offset,10,$_GET,'pending_offset').'</div>';}
